for line in terms.split(';'):
    p=[x.strip() for x in line.split('|')]
    if len(p)!=3: continue
    word,meaning,pos=p
    if not word or any(r['word'].lower()==word.lower() for r in rows): continue
    rows.append(dict(id=len(rows)+1,word=word,v2='—',v3='—',meaning=meaning,part_of_speech=pos.title(),example=f'This is a {word}.',example_id=f'Ini adalah {meaning}.',level='Basic' if len(rows)<350 else ('Intermediate' if len(rows)<500 else 'Advanced')))
